document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("[data-wikipress-menu-builder]").forEach(e=>{e.addEventListener("click",t=>{const a=t.target.closest("[data-wikipress-nav-add]"),s=t.target.closest("[data-wikipress-nav-remove]");if(a){const t=e.querySelector("[data-wikipress-nav-items]");if(!t)return;const s=document.createElement("li");s.className="list-group-item d-flex align-items-center justify-content-between gap-2",s.dataset.wikipressNavItem=a.dataset.wikipressNavAdd,s.innerHTML=`<span>${a.dataset.wikipressNavAddLabel||a.dataset.wikipressNavAdd}</span><button type="button" class="btn btn-sm btn-outline-danger" data-wikipress-nav-remove aria-label="Remove">&times;</button>`,t.appendChild(s)}s&&s.closest("[data-wikipress-nav-item]")?.remove()})})});